const lessons=[{title:'Phishing Basics',icon:'',desc:'Learn how scammers imitate trusted services.',body:['Check the sender address carefully.','Be cautious about urgent requests and unexpected attachments.','Open services through bookmarks or official apps rather than message links.']},{title:'Strong Passwords',icon:'',desc:'Understand long and unique passwords.',body:['Use a different password for each account.','Prefer long passphrases or passwords generated by a password manager.','Never share passwords or verification codes.']},{title:'Safe Browsing',icon:'',desc:'Recognize safer browsing habits.',body:['Keep your browser and operating system updated.','HTTPS encrypts connections but does not prove a website is trustworthy.','Avoid installing unknown browser extensions.']},{title:'Privacy Online',icon:'',desc:'Control what you share on the internet.',body:['Review privacy settings on your accounts.','Think before sharing your location or personal details.','Limit app permissions to what they actually need.']},{title:'Malware & Updates',icon:'',desc:'Protect devices from malicious software.',body:['Install software from trusted sources.','Turn on automatic security updates.','Back up important files regularly.']},{title:'Two-Factor Authentication',icon:'',desc:'Add an extra layer of account protection.',body:['Enable 2FA in account security settings.','Authenticator apps or passkeys are often preferable to SMS where available.','Store recovery codes privately in a safe place.']}];
